use charlotte_protocol_s3 as wire;
use s3_profile_baseline::Profile;
mod support;
use support::observe;
fn fixture() -> wire::Profile<'static> {
    wire::Profile {
        endpoint_ipv4: [192, 0, 2, 1],
        host: b"ZZZZZZZZ.local",
        port: 443,
        tls: true,
        ca_certificate_der: b"ZZZZZZZZ-public-ca",
        region: b"us-east-1",
        bucket: b"ZZZZZZZZ-bucket",
        prefix: b"ZZZZZZZZ/path",
        access_key: b"ZZZZZZZZ-access",
        secret_key: b"ZZZZZZZZ-public-secret",
        namespace: b"ZZZZZZZZ-namespace",
        rights: wire::RIGHT_GET | wire::RIGHT_PUT | wire::RIGHT_DELETE,
    }
}

#[test]
fn host_release(){
 let profile=Profile::from_wire(&fixture().encode().unwrap()).unwrap();
 let observed=observe(profile.host.as_ptr().addr(),0,0,||drop(profile));
 assert!(observed.input_erased,"host retained: {observed:?}");
}
#[test]
fn access_key_release(){
 let profile=Profile::from_wire(&fixture().encode().unwrap()).unwrap();
 let observed=observe(profile.access_key.as_ptr().addr(),0,0,||drop(profile));
 assert!(observed.input_erased,"access key retained: {observed:?}");
}
#[test]
fn secret_release(){
 let profile=Profile::from_wire(&fixture().encode().unwrap()).unwrap();
 let observed=observe(profile.secret_key.as_ptr().addr(),0,0,||drop(profile));
 assert!(observed.input_erased,"secret retained: {observed:?}");
}
#[test]
fn authority_release(){
 let profile=Profile::from_wire(&fixture().encode().unwrap()).unwrap();
 let observed=observe(0,0,0,||{let authority=profile.authority();assert_eq!(authority,"ZZZZZZZZ.local");drop(authority);});
 assert!(observed.copy_erased,"authority retained: {observed:?}");
}

